def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(
        (list(interval) for interval in intervals),
        key=lambda interval: (interval[0], interval[1])
    )

    merged = [sorted_intervals[0]]

    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if start <= last_end:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

import heapq

def toposort(nodes, edges):
    indegree = {node: 0 for node in nodes}
    successors = {node: set() for node in nodes}

    for source, destination in edges:
        if destination not in successors[source]:
            successors[source].add(destination)
            indegree[destination] += 1

    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)
    result = []

    while ready:
        node = heapq.heappop(ready)
        result.append(node)

        for nxt in sorted(successors[node]):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(result) != len(nodes):
        raise ValueError("cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError

    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError

    batches = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if not current_batch or current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight

    if current_batch:
        batches.append(current_batch)

    return batches

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

def parse_env(text: str) -> dict:
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"Invalid environment line: {raw_line!r}")
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        if _KEY_RE.fullmatch(key) is None:
            raise ValueError(f"Invalid environment key: {key!r}")
        env[key] = value
    return env

from typing import List

def parse_sse(chunks: List[bytes]) -> List[str]:
    events: List[str] = []
    data_lines: List[bytes] = []
    buf = b""
    done = False

    def dispatch() -> bool:
        nonlocal data_lines, done
        lines = data_lines
        data_lines = []
        if not lines:
            return False
        event_data = b"\n".join(lines).decode("utf-8")
        if event_data == "[DONE]":
            done = True
            return True
        events.append(event_data)
        return False

    for chunk in chunks:
        buf += chunk
        while True:
            idx = buf.find(b"\n")
            if idx == -1:
                break
            line = buf[:idx]
            buf = buf[idx + 1 :]
            if line.endswith(b"\r"):
                line = line[:-1]

            if line == b"":
                if dispatch():
                    return events
            elif line.startswith(b":"):
                continue
            else:
                colon = line.find(b":")
                if colon != -1 and line[:colon] == b"data":
                    value = line[colon + 1 :]
                    if value.startswith(b" "):
                        value = value[1:]
                    data_lines.append(value)

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("retry_delay arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    if attempt == 0:
        return float(min(cap, base))
    try:
        result = math.ldexp(base, attempt)
    except OverflowError:
        return float(cap)
    if math.isinf(result) or math.isnan(result):
        return float(cap)
    if result > cap:
        return float(cap)
    return float(result)

def fifo_admit(active, queued, budget, slots):
    if any(token > budget for token in queued):
        raise ValueError("Queued reservation exceeds budget")

    admitted = []
    remaining = []

    remaining_budget = budget - sum(active)
    used_slots = len(active)

    for i, token in enumerate(queued):
        if token > remaining_budget or used_slots >= slots:
            remaining = queued[i:]
            break

        admitted.append(token)
        remaining_budget -= token
        used_slots += 1
    else:
        remaining = []

    return (admitted, remaining)
